    Select treats a silent store like an absent one (auto: git helper then
    memory; pinned keyring: memory) and its Detail says the store did not
    answer, is probably locked, and how to get out of it.

    Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
    Entire-Checkpoint: e12435fdf0a7

 .claude/CLAUDE.md                            |   6 +-
 docs/architecture/configuration.md           |  43 ++++-
 internal/credentials/hoststore.go            |  18 +-
 internal/credentials/hoststore_bound.go      | 113 +++++++++++++
 internal/credentials/keyring.go              |  16 +-
 internal/credentials/keyring_timeout_test.go | 238 +++++++++++++++++++++++++++
 internal/credentials/select.go               |  32 +++-
 7 files changed, 454 insertions(+), 12 deletions(-)
package credentials

import (
	"errors"
	"sync"
	"time"
)

// keyringTimeout bounds every call to the host secret store (DEVDESK-745).
//
// go-keyring has no deadline of its own. On Linux, a read from a locked Secret
// Service collection asks the daemon to unlock it, and go-keyring then waits
// for the prompt's Completed signal with no timeout: in an SSH session, where
// no prompt can be shown or answered, the wait never ends. Select runs before
// the first frame, so the screen stayed blank.
//
// Three seconds is longer than a store that answers ever takes (a few
// milliseconds over D-Bus) and short enough for a launch that has to give up
// on it. A variable only so the tests of this package can shorten it.
var keyringTimeout = 3 * time.Second

// ErrKeyringUnresponsive is returned by a host store call that did not answer
// within keyringTimeout, and at once by every later call while that one is
// still blocked.
var ErrKeyringUnresponsive = errors.New("the host secret store did not answer in time")

// boundedHost runs each call of the store in box with a deadline.
//
// A call that misses the deadline is abandoned, not cancelled: the HostStore
// interface has no context and go-keyring offers no way to stop a wait, so the
// goroutine running it stays blocked until the store answers, possibly for the
// rest of the process (one goroutine and one D-Bus connection). While such a
// call is pending, every new call fails at once with ErrKeyringUnresponsive
// instead of waiting again and leaking another goroutine: a store judged mute
// is not probed again until it has answered the call that was stuck.
type boundedHost struct{ box *hostBox }

func (h boundedHost) Get(service, account string) (string, error) {
	return h.call(func(s HostStore) (string, error) { return s.Get(service, account) })
}

func (h boundedHost) Set(service, account, secret string) error {
	_, err := h.call(func(s HostStore) (string, error) { return "", s.Set(service, account, secret) })
	return err
}

func (h boundedHost) Delete(service, account string) error {
	_, err := h.call(func(s HostStore) (string, error) { return "", s.Delete(service, account) })
	return err
}

// hostResult is what a call to the store produced. panicked carries a panic
// (the DEVDESK-610 test guard) back to the caller's goroutine, so it still
// fails the test that reached the store.
type hostResult struct {
	secret   string
	err      error
	panicked any
}

func (r hostResult) unwrap() (string, error) {
	if r.panicked != nil {
		panic(r.panicked)
	}
	return r.secret, r.err
}

func (h boundedHost) call(op func(HostStore) (string, error)) (string, error) {
	box := h.box
	if box.stuck.Load() > 0 {
		return "", ErrKeyringUnresponsive
	}

	var mu sync.Mutex
	abandoned := false
	done := make(chan hostResult, 1)
	go func() {
		var r hostResult
		defer func() {
			if p := recover(); p != nil {
				r.panicked = p
			}
			// The result is delivered under the lock, so the caller either
			// sees it or has already counted this call as stuck, never neither.
			mu.Lock()
			defer mu.Unlock()
			if abandoned {
				box.stuck.Add(-1)
			}
			done <- r
		}()
		r.secret, r.err = op(box.store)
	}()

	timer := time.NewTimer(keyringTimeout)
	defer timer.Stop()
	select {
	case r := <-done:
		return r.unwrap()
	case <-timer.C:
	}

	mu.Lock()
	defer mu.Unlock()
	select {
	case r := <-done:
		return r.unwrap()
	default:
	}
	abandoned = true
	box.stuck.Add(1)
	return "", ErrKeyringUnresponsive
}

package credentials

import (
	"errors"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// hangingHost is a HostStore that never answers until it is released: what the
// Secret Service does when its collection is locked and the unlock prompt it
// raised cannot be shown or answered (an SSH session, DEVDESK-745).
type hangingHost struct {
	release chan struct{}
	calls   *atomic.Int32
}

func (h hangingHost) wait() { h.calls.Add(1); <-h.release }

func (h hangingHost) Get(string, string) (string, error) { h.wait(); return "", ErrNotFound }
func (h hangingHost) Set(string, string, string) error   { h.wait(); return nil }
func (h hangingHost) Delete(string, string) error        { h.wait(); return nil }

// useHangingHost installs a store that blocks every call until the test ends,
// or until the returned release is called. The release runs before the store
// is swapped back, so no goroutine is left blocked once the test is over.
func useHangingHost(t *testing.T) (h hangingHost, release func()) {
	t.Helper()
	h = hangingHost{release: make(chan struct{}), calls: new(atomic.Int32)}
	prev := SwapHostStoreForTest(h)
	var once sync.Once
	release = func() { once.Do(func() { close(h.release) }) }
	t.Cleanup(func() { SwapHostStoreForTest(prev) })
	t.Cleanup(release)
	return h, release
}

// shortKeyringTimeout shortens the bound for the test, so the cases that do
// not check the production value do not each wait three seconds.
func shortKeyringTimeout(t *testing.T) {
	t.Helper()
	prev := keyringTimeout
	keyringTimeout = 50 * time.Millisecond
	t.Cleanup(func() { keyringTimeout = prev })
}

// returnsWithin runs fn and fails the test if it has not returned after limit.
func returnsWithin[T any](t *testing.T, limit time.Duration, fn func() T) T {
	t.Helper()
	done := make(chan T, 1)
	go func() { done <- fn() }()
	select {
	case v := <-done:
		return v
	case <-time.After(limit):
		t.Fatalf("still blocked after %v: a host store that never answers freezes the caller", limit)
		var zero T
		return zero
	}
}

// watchdog is the bound plus a margin for a loaded CI runner.
const watchdog = 5 * time.Second

// silenceWords is what a Detail says when the host store did not answer: that
// it did not, the likely cause, and the two ways out.
var silenceWords = []string{"did not answer", "locked", "unlock it", "app.secret_backend"}

func requireSilenceExplained(t *testing.T, detail string) {
	t.Helper()
	for _, want := range append(silenceWords, KeyringName()) {
		if !strings.Contains(detail, want) {
			t.Errorf("Detail = %q, want it to contain %q", detail, want)
		}
	}
}

// This case keeps the production bound: it is the one that proves DevDesk's
// launch no longer waits forever, and how long it does wait.
func TestSelectDoesNotWaitForAHostStoreThatNeverAnswers(t *testing.T) {
	useHangingHost(t)
	hermeticGitWithHelper(t, "store")

	start := time.Now()
	sel := returnsWithin(t, watchdog, func() Selection { return Select("work", PreferenceKeyring) })
	if waited := time.Since(start); waited < 3*time.Second {
		t.Errorf("Select gave up after %v, want the 3s bound", waited)
	}

	if sel.Backend != BackendMemory {
		t.Fatalf("Backend = %q, want %q", sel.Backend, BackendMemory)
	}
	if !strings.Contains(sel.Detail, "Nothing is saved") {
		t.Errorf("Detail = %q, want it to say that nothing is saved", sel.Detail)
	}
	requireSilenceExplained(t, sel.Detail)
}

func TestSelectAutoSkipsASilentHostStore(t *testing.T) {
	tests := []struct {
		name   string
		helper string
		want   Backend
	}{
		{"to the git helper when one is usable", "manager", BackendGitCredential},
		{"to memory when none is", "store", BackendMemory},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			shortKeyringTimeout(t)
			useHangingHost(t)
			hermeticGitWithHelper(t, tt.helper)

			sel := returnsWithin(t, watchdog, func() Selection { return Select("work", PreferenceAuto) })

			if sel.Backend != tt.want {
				t.Fatalf("Backend = %q, want %q", sel.Backend, tt.want)
			}
			requireSilenceExplained(t, sel.Detail)
		})
	}
}

// An absent store keeps its own message: "did not answer" is only for a store
// that is there and silent, which the user can do something about.
func TestSelectKeepsTheAbsentStoreMessage(t *testing.T) {
	unreachableKeyring(t)
	hermeticGitWithHelper(t, "store")

	for _, pref := range []string{PreferenceAuto, PreferenceKeyring} {
		if d := Select("work", pref).Detail; strings.Contains(d, "did not answer") {
			t.Errorf("Select(%q).Detail = %q, says the store did not answer although it is absent", pref, d)
		}
	}
}

// Every KeyringStorage operation is bounded, not only the probe: a token read
// later in the session would otherwise freeze the view that asked for it.
func TestKeyringStorageOperationsAreBounded(t *testing.T) {
	tests := []struct {
		name string
		call func(*KeyringStorage) error
	}{
		{"Save", func(k *KeyringStorage) error { return k.Save("https://h.example", "secret") }},
		{"Load", func(k *KeyringStorage) error { _, err := k.Load("https://h.example"); return err }},
		{"Delete", func(k *KeyringStorage) error { return k.Delete("https://h.example") }},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			shortKeyringTimeout(t)
			useHangingHost(t)
			k := NewKeyringStorage("work")

			err := returnsWithin(t, watchdog, func() error { return tt.call(k) })

			if !errors.Is(err, ErrKeyringUnresponsive) {
				t.Fatalf("%s error = %v, want ErrKeyringUnresponsive", tt.name, err)
			}
			if !strings.Contains(err.Error(), KeyringName()) {
				t.Errorf("%s error = %q, want it to name %q", tt.name, err, KeyringName())
			}
		})
	}
}

// Once a call is stuck, the store is not asked again while it stays stuck:
// each new call fails at once instead of freezing for the bound again and
// leaving one more goroutine behind.
func TestASilentHostStoreIsNotProbedAgain(t *testing.T) {
	shortKeyringTimeout(t)
	h, _ := useHangingHost(t)

	if KeyringAvailable() {
		t.Fatal("KeyringAvailable() = true for a store that never answers")
	}
	start := time.Now()
	for range 5 {
		if KeyringAvailable() {
			t.Fatal("KeyringAvailable() = true for a store that never answers")
		}
		if _, err := NewKeyringStorage("work").Load("https://h.example"); !errors.Is(err, ErrKeyringUnresponsive) {
			t.Fatalf("Load error = %v, want ErrKeyringUnresponsive", err)
		}
	}
	if waited := time.Since(start); waited >= keyringTimeout {
		t.Errorf("ten later calls took %v, want them to fail at once", waited)
	}
	if got := h.calls.Load(); got != 1 {
		t.Errorf("the store was called %d times, want 1", got)
	}
}

// A store that answers the stuck call (the user unlocked it) is asked again.
func TestAHostStoreThatAnswersLateIsUsedAgain(t *testing.T) {
	shortKeyringTimeout(t)
	h, release := useHangingHost(t)

	if KeyringAvailable() {
		t.Fatal("KeyringAvailable() = true for a store that never answers")
	}
	release()

	deadline := time.Now().Add(watchdog)
	for !KeyringAvailable() {
		if time.Now().After(deadline) {
			t.Fatal("the store answered its stuck call but is still treated as silent")
		}
		time.Sleep(5 * time.Millisecond)
	}
	if got := h.calls.Load(); got < 2 {
		t.Errorf("the store was called %d times, want it asked again after it answered", got)
	}
}

// A store that answers just after the bound is not counted as stuck forever:
// the stuck count goes back to zero once the late call returns.
func TestTheStuckCountReturnsToZero(t *testing.T) {
	shortKeyringTimeout(t)
	_, release := useHangingHost(t)
	box := currentStore.Load()

	for range 3 {
		_ = KeyringAvailable()
	}
	if got := box.stuck.Load(); got != 1 {
		t.Fatalf("stuck = %d after one timed-out call and two refused ones, want 1", got)
	}
	release()
	deadline := time.Now().Add(watchdog)
	for box.stuck.Load() != 0 {
		if time.Now().After(deadline) {
			t.Fatalf("stuck = %d after the store answered, want 0", box.stuck.Load())
		}
		time.Sleep(5 * time.Millisecond)
	}
}
package credentials

import (
	"errors"
	"fmt"
	"sync/atomic"
	"testing"

	"github.com/zalando/go-keyring"
)

// hostStoreUnderTestMessage is the panic text of refuseUnderTest. It names what
// to do, because the person reading it is a developer whose test just reached
// the real secret store of the machine (DEVDESK-610).
const hostStoreUnderTestMessage = "credentials: a test reached the host secret store (%s) " +
	"without isolation; call fakekeyring.Install() in TestMain or fakekeyring.Fresh(t) " +
	"(DEVDESK-610, docs/architecture/configuration.md)"

// HostStore is the host secret manager as KeyringStorage and KeyringAvailable
// see it. The contract on a missing entry:
//   - Get returns an error for which errors.Is(err, ErrNotFound). go-keyring's
//     own ErrNotFound is not recognized here; goKeyring maps it.
//   - Delete returns nil.
//
// An implementation that returns any other error for a missing entry is seen as
// a real failure of the store: KeyringAvailable reports it unreachable.
type HostStore interface {
	Get(service, account string) (string, error)
	Set(service, account, secret string) error
	Delete(service, account string) error
}

// hostBox lets an atomic.Pointer hold an interface value, so a Cmd reading the
// current store while a t.Cleanup restores the previous one is not a data race.
// It also carries the count of calls to that store that outlived
// keyringTimeout (see boundedHost): a swap starts a fresh count.
type hostBox struct {
	store HostStore
	stuck atomic.Int32
}

var currentStore atomic.Pointer[hostBox]

// defaultBox holds the production store when no test swapped it. It is a
// single value so that its stuck count lasts for the whole process.
var defaultBox = &hostBox{store: goKeyring{}}

// hostReachableUnderTest is set only by the TestMain of this package, whose
// tests mock go-keyring themselves and run git against a hermetic config. In
// any other test binary it stays false, so the real store is refused.
var hostReachableUnderTest atomic.Bool

// currentHost returns the store in use, goKeyring{} unless a test swapped it,
// with every call bounded by keyringTimeout (DEVDESK-745).
func currentHost() HostStore {
	if b := currentStore.Load(); b != nil {
		return boundedHost{box: b}
	}
	return boundedHost{box: defaultBox}
}

// SwapHostStoreForTest installs s and returns the store it replaces. It panics
// outside a test binary and when s is nil. Only _test.go files and
// internal/testutil/fakekeyring may call it.
func SwapHostStoreForTest(s HostStore) HostStore {
	if !testing.Testing() {
		panic("credentials: SwapHostStoreForTest called outside a test binary")
	}
	if s == nil {
		panic("credentials: SwapHostStoreForTest called with a nil HostStore; pass the store to restore, as returned by the previous call")
	}
	if prev := currentStore.Swap(&hostBox{store: s}); prev != nil {
		return prev.store
	}
	return goKeyring{}
}

// refuseUnderTest panics with hostStoreUnderTestMessage when the code runs in a
// test binary that has not allowed the real host store. It panics rather than
// returning an error: an error would make Select fall back to memory and the
// test would pass, leaving the guard silent. op names the operation reached.
func refuseUnderTest(op string) {
	if testing.Testing() && !hostReachableUnderTest.Load() {
		panic(fmt.Sprintf(hostStoreUnderTestMessage, op))
	}
}

// goKeyring is the production HostStore and the only place go-keyring is
// called. Every method runs the test guard first.
type goKeyring struct{}

func (goKeyring) Get(service, account string) (string, error) {
	refuseUnderTest("keyring get")
	secret, err := keyring.Get(service, account)
	if errors.Is(err, keyring.ErrNotFound) {
		return "", fmt.Errorf("%w: %v", ErrNotFound, err)
	}
	return secret, err
}

func (goKeyring) Set(service, account, secret string) error {
	refuseUnderTest("keyring set")
	return keyring.Set(service, account, secret)
}

func (goKeyring) Delete(service, account string) error {
	refuseUnderTest("keyring delete")
	err := keyring.Delete(service, account)
	if errors.Is(err, keyring.ErrNotFound) {
		return nil
	}
	return err
}

package credentials

import (
	"log"

	"github.com/anthnel/devdesk/internal/config"
)

// MigrateLegacySecrets moves the plaintext secrets an earlier DevDesk left in a
// context's configuration file into the store, then deletes them from the file.
//
// It runs on load. Dropping the fields from the schema and ignoring whatever is
// in the file would leave every existing user's token on disk forever, which is
// the opposite of what §3.9 asks for.
//
// The returned lines describe what happened, in the user's words, and are empty
// when there was nothing to migrate — the normal case. A secret that could not
// be stored stays in the file: losing it would be worse than leaving it.
func MigrateLegacySecrets(store Storage, contextName string) []string {
	legacy, err := config.ReadLegacySecrets(contextName)
	if err != nil {
		log.Printf("ERROR [credentials/migrate] read legacy secrets for context %q: %v", contextName, err)
		return nil
	}
	if legacy.Empty() {
		return nil
	}

	var notes []string
	movedToken := false
	movedPassword := false

	if legacy.GitLabToken != "" {
		movedToken, notes = migrateOne(store, legacy.GitLabURL, legacy.GitLabToken, "GitLab token", notes)
	}
	if legacy.RegistryPassword != "" {
		movedPassword, notes = migrateOne(store, legacy.RegistryURL, legacy.RegistryPassword, "registry password", notes)
	}

	if movedToken || movedPassword {
		if err := config.RemoveLegacySecrets(contextName, movedToken, movedPassword); err != nil {
			log.Printf("ERROR [credentials/migrate] strip legacy secrets from context %q: %v", contextName, err)
			return append(notes, "The plaintext copy could not be removed from the configuration file — delete it by hand.")
		}
	}
	return notes
}

// migrateOne stores a single secret and reports whether the file copy may now
// be deleted.
//
// A secret with no URL is dropped rather than stored: the URL is the key it
// would be filed under, and DevDesk cannot use a token it has no host for. That
// makes it unusable plaintext, and keeping unusable plaintext on disk is the
// one outcome worth avoiding — so it goes, and the user is told it went.
func migrateOne(store Storage, url, secret, label string, notes []string) (bool, []string) {
	if url == "" {
		log.Printf("credentials/migrate: dropping %s with no URL to key it on", label)
		return true, append(notes, "A "+label+" was removed from the configuration file: it had no URL and could not be used.")
	}

	if err := store.Save(url, secret); err != nil {
		log.Printf("ERROR [credentials/migrate] store %s for %s: %v", label, url, err)
		return false, append(notes, "The "+label+" is still in plaintext in the configuration file: "+err.Error())
	}

	log.Printf("credentials/migrate: moved %s for %s out of the configuration file", label, url)
	return true, append(notes, "The "+label+" moved out of the configuration file and into the secret store.")
}
	}
	return &KeyringStorage{context: contextName}
}

// account builds the key a secret is filed under. The context comes first so
// that the entries of one context sort together when a user browses the store
// by hand.
func (k *KeyringStorage) account(url string) string {
	return k.context + "/" + url
}

// Save writes the secret to the host store, replacing any previous value.
func (k *KeyringStorage) Save(url, secret string) error {
	if err := currentHost().Set(keyringService, k.account(url), secret); err != nil {
		return fmt.Errorf("%s: %w", KeyringName(), err)
	}
	return nil
}

// Load reads the secret back. A missing entry is an error, matching the rest of
// the Storage implementations.
func (k *KeyringStorage) Load(url string) (string, error) {
	secret, err := currentHost().Get(keyringService, k.account(url))
	if errors.Is(err, ErrNotFound) {
		return "", fmt.Errorf("%w for %s (context: %s)", ErrNotFound, url, k.context)
	}
	if err != nil {
		return "", fmt.Errorf("%s: %w", KeyringName(), err)
	}
	return secret, nil
}

// Delete removes the secret. Deleting one that is not there succeeds: logout
// must not fail because the token was already gone.
func (k *KeyringStorage) Delete(url string) error {
	err := currentHost().Delete(keyringService, k.account(url))
	if err == nil || errors.Is(err, ErrNotFound) {
		return nil
	}
	return fmt.Errorf("%s: %w", KeyringName(), err)
}

